SELECT CAST(AVG(CASE WHEN p.dischtime IS NOT NULL THEN a.los END) AS FLOAT) AS avg_los_alive, CAST(AVG(CASE WHEN p.dischtime IS NULL THEN a.los END) AS FLOAT) AS avg_los_dead, CAST(AVG(CASE WHEN p.dischtime IS NOT NULL THEN a.los END) AS FLOAT) / NULLIF(AVG(CASE WHEN p.dischtime IS NULL THEN a.los END), 0) AS ratio_alive_to_dead, PERCENT_RANK() OVER (ORDER BY a.los) AS percentile_rank FROM physionet-data.mimiciv_3_1_hosp.admissions a JOIN physionet-data.mimiciv_3_1_hosp.patients p ON a.subject_id = p.subject_id WHERE p.gender = 'M' AND p.anchor_age BETWEEN 57 AND 67 AND a.admission_type = 'Medicine' AND a.dischtime IS NOT NULL AND p.dod IS NULL AND EXTRACT(DAY FROM (a.dischtime - a.admittime)) = 5;